import assert from "node:assert/strict";
import { test } from "node:test";

import { Inventory } from "../../shop/inventory.js";

test("release returns reserved stock", () => {
  const inv = new Inventory({ "MUG-01": 50 });
  inv.reserve("MUG-01", 2);
  inv.release("MUG-01", 2);
  assert.equal(inv.reserved("MUG-01"), 0);
  assert.equal(inv.available("MUG-01"), 50);
});

test("partial releases accumulate", () => {
  const inv = new Inventory({ "MUG-01": 50 });
  inv.reserve("MUG-01", 3);
  inv.release("MUG-01", 1);
  inv.release("MUG-01", 2);
  assert.equal(inv.reserved("MUG-01"), 0);
});

import assert from "node:assert/strict";
import { test } from "node:test";

import { Cart } from "../../shop/cart.js";
import { makeShop } from "../helpers.js";

test("buy-again cart edits do not change the past order", () => {
  const { cart, orders, user, catalog } = makeShop();
  cart.add("MUG-01", 2);
  const order = orders.checkout(cart, user);
  const again = orders.buyAgain(order.id, new Cart(catalog));
  again.add("MUG-01", 3);
  assert.equal(order.lines[0].quantity, 2);
});

test("cancel after buy again succeeds", () => {
  const { cart, orders, user, catalog, inventory } = makeShop();
  cart.add("MUG-01", 2);
  const order = orders.checkout(cart, user);
  orders.buyAgain(order.id, new Cart(catalog)).add("MUG-01", 3);
  orders.cancel(order.id);
  assert.equal(inventory.reserved("MUG-01"), 0);
});

